let particles = [];
const MAX_PARTICLES = 500;
const MIN_SIZE = 10;
const MAX_SIZE = 300;
const MAX_SPEED = 8;

function setup() {

  //canvas description for screen readers
  describe('A solid background with randomly placed particles that appear and then fade over time.');


  createCanvas(windowWidth, windowHeight);

  // Initialize particles array
  for (let i = 0; i < MAX_PARTICLES; i++) {
    const x = random(width);
    const y = random(height);
    let size_custom = random(MIN_SIZE, MAX_SIZE);

    // Define particle color
    const hue = random(360);
    const saturation = random(70) + 30;
    const brightness = random(90) + 10;

    particles[i] = new Particle(x, y, size_custom, [hue, saturation, brightness]);
  }
}

function draw() {
  background('#ffffff');

  // Update and display each particle
  for (let i = 0; i < particles.length; i++) {
    const particle = particles[i];

    if (!particle.isDead()) {
      //const mouseAngle = atan2((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - particle.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - particle.x);

      // Apply forces to the particle based on mouse position
      //const forceMagnitude = map(dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), particle.x, particle.y), 0, width/2, 0.01, 0.1);
      //const forceX = cos(mouseAngle) * forceMagnitude;
      //const forceY = sin(mouseAngle) * forceMagnitude;

      //particle.applyForce(forceX, forceY);

      particle.update();
      particle.display();
    } else {
      // Remove dead particles from the array
      particles.splice(i, 1);
      i--;
    }
  }

  // Add new particles when fewer than max count
  if (particles.length < MAX_PARTICLES) {
    var x = random(width);
    var y = random(height);
    var size_custom = random(MIN_SIZE, MAX_SIZE);

    // Define particle color
    var hue = random(360);
    var saturation = random(70) + 30;
    var brightness = random(90) + 10;

    particles.push(new Particle(x, y, size_custom, [hue, saturation, brightness]));
  }
}

class Particle {
  constructor(x, y, size_custom, color) {
    this.position = createVector(x, y);
    this.velocity = createVector();
    this.acceleration = createVector();
    this.size_custom = size_custom;
    this.color = color;
    this.lifespan = random(255);
  }

  applyForce(forceX, forceY) {
    const force = createVector(forceX, forceY);
    this.acceleration.add(force);
  }

  update() {
    this.velocity.limit(MAX_SPEED);
    this.velocity.add(this.acceleration);
    this.position.add(this.velocity);
    this.acceleration.mult(1);
    this.lifespan -= 0.8; // relates to how fast new particles appear


    // Reduce life span and size gradually
    this.lifespan -= 0.01;     // how fast the particles disappear
    this.size_custom *= 0.98; // how fast the particles shrink


  }

  display() {
    noStroke();
		//let channel_red   = this.color[0];
		//let channel_green = this.color[1];
		let channel_red   = 255;
		let channel_green = 20;
		let channel_blue  = this.color[2];
		let channel_alpha = this.lifespan;
    fill(channel_red,channel_green,channel_blue,channel_alpha);
    circle(this.position.x, this.position.y, this.size_custom);
  }

  isDead() {
    return this.lifespan <= 0 || this.size_custom <= 0;
  }
}

